//! Finite transform methods and B05 result specialization retain typed failures.
use super::*;
impl Analyzer{
 pub(super) fn compression_call(&mut self,context:&mut Context,expression:&mut Expr,loans:&Loans,expected:Option<Type>)->Result<Option<Type>,Diagnostic>{let ExprKind::Call(callee,args)=&expression.kind else{return Ok(None)};let ExprKind::Field(receiver,name)=&callee.kind else{return Ok(None)};let Some(Type::Record(record))=self.expression_type_hint(context,receiver)else{return Ok(None)};let Some(binding)=crate::stdlib::compression::method(self.program.records[record].native_type,name)else{return Ok(None)};let mut arguments=vec![(**receiver).clone()];arguments.extend(args.iter().cloned());crate::stdlib::futures::lazy_result(expression,"std:compression",binding.name,arguments);self.expression(context,expression,Mode::Consume,loans,expected).map(Some)}
 pub(super) fn compression_io_result(&self,binding:&crate::native_bindings::NativeBinding,args:&[Expr])->Option<Type>{use crate::native_signatures::NativeTypeId;if binding.module!="std:io"{return None;}let compression=args.iter().filter_map(|arg|if let Some(Type::Record(record))=arg.ty{self.program.records[record].native_type}else{None}).any(|identity|matches!(identity,NativeTypeId::CompressionReader|NativeTypeId::CompressionWriter));if !compression{return None;}let writer=args.first().and_then(|arg|arg.ty).is_some_and(|ty|matches!(ty,Type::Record(record)if self.program.records[record].native_type==Some(NativeTypeId::CompressionWriter)));let operation=crate::stdlib::compression::io_operation(binding.name.trim_start_matches('_'),writer)?;Some(native_type(operation.result,&self.program.records))}
}
